import{z as E,x as p,o,c as m,q as r,j as s,D as i,d as t,s as d,S as l,b as n}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Edmonds–Karp 与 Dinic","description":"","frontmatter":{"title":"Edmonds–Karp 与 Dinic","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dinic.md","filePath":"cs/dinic.md","lastUpdated":1791413859000}'),c={name:"cs/dinic.md"};function B(A,a,D,h,f,C){const e=p("Mermaid");return o(),m("div",null,[a[2]||(a[2]=r('<h1 id="edmonds–karp-与-dinic" tabindex="-1">Edmonds–Karp 与 Dinic <a class="header-anchor" href="#edmonds–karp-与-dinic" aria-label="Permalink to &quot;Edmonds–Karp 与 Dinic&quot;">​</a></h1><div class="epigraph"><p>最短增广把 Ford–Fulkerson 变成 $O(VE^2)$；分层网络上的阻塞流把迭代降到 $O(V^2 E)$。</p><footer>—— 据 Edmonds and Karp, Theoretical Improvements in Algorithmic Efficiency for Network Flow Problems, 1972；Dinic, Algorithm for Solution of a Problem of Maximum Flow, 1970；CLRS 第 26 章整理</footer></div><p>上一课<a href="/cs/max-flow-ff">最大流 Ford–Fulkerson</a>给出残量增广与最大流最小割，并警告：任意增广路可使次数随容量指数。本课不重证割。缺口是<strong>选哪条路</strong>：Edmonds–Karp 每次 BFS 最短（边数最少）增广；Dinic 一次建分层，再推阻塞流。整数容量下二者都多项式。后课二分图匹配把单位容量网络当特例。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Ford–Fulkerson 是框架。容量很大且每次 \\(\\Delta=1\\) 时，增广次数可达 \\(\\Theta(|f^*|)\\)。Edmonds–Karp：残量上 BFS 找 \\(s\\)–\\(t\\) 最短路再增。关键事实：最短路长度不减，每条边作为临界边的次数 \\(O(V)\\)，故增广 \\(O(VE)\\) 次，每次 \\(O(E)\\)，总 \\(O(VE^2)\\)。缺口是这份选路规则，不是新的流定义。</p><p>Dinic：按残量 BFS 分层，\\(d(v)\\) 为边数距离。只沿层间边 \\(d(w)=d(v)+1\\) 推流，直到 \\(s\\) 到 \\(t\\) 不再连通（阻塞流）。然后重建分层。层数增加，至多 \\(V-1\\) 相。单位容量或简单图上实现可到 \\(O(V^2 E)\\) 量级（经典界）；更紧的实现不在本课展开。</p><p><span class="marginnote">术语翻译：「增广路」就是一条从 \\(s\\) 到 \\(t\\)、每段都还有剩余容量的路径；一次能塞的流量等于路上最窄那段的剩余量（瓶颈）。数字实例：路径 \\(s\\to a\\to t\\) 上 \\(s\\to a\\) 剩 3、\\(a\\to t\\) 剩 5，则本次只能增广 \\(\\min(3,5)=3\\)，且 \\(a\\to t\\) 还剩 2 给下一条路用。</span></p><h3 id="阻塞流不是一次增广" tabindex="-1">阻塞流不是一次增广 <a class="header-anchor" href="#阻塞流不是一次增广" aria-label="Permalink to &quot;阻塞流不是一次增广&quot;">​</a></h3><p>一次阻塞流可以同时填满分层里的许多条路，相当于一批最短增广。Dinic 1970 的「功率」估计即分层推进。不要把 Dinic 写成「再跑一遍 Edmonds–Karp」。</p><p><span class="marginnote">Edmonds–Karp 1972 证明最短增广多项式。Dinic（Dinitz）1970 更早给出分层。CLRS 以 Edmonds–Karp 为定理级实现，Dinic 作进阶。本课两条都要：一条证明墙是多项式，一条给更常用的推进。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>EK：循环 BFS，沿树增广，更新残量，直至 \\(t\\) 不可达。Dinic：循环 { BFS 分层；若 \\(t\\) 不在分层则停；DFS/指针沿层推阻塞流 }。</p>',12)),(o(),s(l,null,{default:i(()=>[d(e,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FF%5B%22%E6%AE%8B%E9%87%8F%E5%8F%AF%E5%A2%9E%E5%B9%BF%22%5D%20--%3E%20EK%5B%22BFS%20%E6%9C%80%E7%9F%AD%E5%A2%9E%E5%B9%BF%20O(VE%5E2)%22%5D%0A%20%20FF%20--%3E%20DIN%5B%22%E5%88%86%E5%B1%82%20%2B%20%E9%98%BB%E5%A1%9E%E6%B5%81%22%5D%0A%20%20DIN%20--%3E%20POLY%5B%22%E5%A4%9A%E9%A1%B9%E5%BC%8F%E7%9B%B8%E6%95%B0%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("p",null,"容量有理先化为整数。无理容量仍可能病态，主干用整数。",-1)),a[4]||(a[4]=n("h2",{id:"机制",tabindex:"-1"},[t("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=n("p",null,"最短增广使「距离标号」单调，分析才能数临界边。Dinic 的当前弧优化避免反复扫邻接表，是实现零件，不改变分层正确性。单位容量网络（匹配）上界更好，下一课用，本课不把匹配写完。",-1)),(o(),s(l,null,{default:i(()=>[d(e,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20S%5B%22s%EF%BC%9A%E7%AC%AC%200%20%E5%B1%82%22%5D%20--%3E%20A%5B%22a%EF%BC%9A%E7%AC%AC%201%20%E5%B1%82%22%5D%0A%20%20S%20--%3E%20B%5B%22b%EF%BC%9A%E7%AC%AC%201%20%E5%B1%82%22%5D%0A%20%20A%20--%3E%20C%5B%22c%EF%BC%9A%E7%AC%AC%202%20%E5%B1%82%22%5D%0A%20%20B%20--%3E%20C%0A%20%20A%20--%3E%20T%5B%22t%EF%BC%9A%E7%AC%AC%202%20%E5%B1%82%22%5D%0A%20%20C%20--%3E%20T%0A%20%20A%20-.-%3E%7C%22%E5%90%8C%E5%B1%82%E8%BE%B9%EF%BC%9A%E7%A6%81%E8%B5%B0%22%7C%20B%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>这张图回答「分层网络长什么样」：BFS 给每个点标上到 \\(s\\) 的边数距离，阻塞流只允许沿「第 \\(i\\) 层 \\(\\to\\) 第 \\(i+1\\) 层」的边推；同层边和往回走的边一律不碰。当 \\(t\\) 被推到与 \\(s\\) 断开（图中 \\(c\\to t\\)、\\(a\\to t\\) 全饱和），这一相结束，残量重建分层后层数至少加一。</p><p><span class="marginnote">直觉类比：分层像消防演习里按离出口的步数排队，水流只许从第 \\(i\\) 排传给第 \\(i+1\\) 排，绝不许在同学之间横着传、也不许往后传。这样每条被推的路都恰好是最短路长度，\\(t\\) 的层数只增不减，所以至多 \\(V-1\\) 相就穷尽。</span></p><p>不要在有负容量的「流」上套本课；模型仍是上一课的容量约束与守恒。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写推送重标、不写费用流。最小割在增广结束时仍是 \\(s\\) 侧可达集。后课默认：要多项式最坏，最短增广或 Dinic；二分图匹配化成单位容量最大流。</p><p><span class="marginnote">常见误区：初学者容易以为最小割要在最大流之外「再单独算一次」。实际上最大流一结束，在残量网络上从 \\(s\\) 还能走到的那个点集，把它射向外的所有边割断，恰好就是一个最小割——最大流最小割定理保证两边数值相等，不用再找。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Edmonds–Karp：最短增广，\\(O(VE^2)\\)。</li><li>Dinic：分层阻塞流，相数 \\(O(V)\\)。</li><li>仍是残量增广；选路决定次数。</li><li>出处：Dinic, 1970；Edmonds and Karp, 1972；CLRS 第 26 章。</li></ul>',8))])}const S=E(c,[["render",B]]);export{u as __pageData,S as default};
